  choices = $EXPL$["Deploy micro-segmentation across all existing network zones immediately","Replace all legacy firewalls with next-generation firewall models","Require biometric authentication for all users across the organization","Identify and classify all assets, data flows, and users needing protection"]$EXPL$::jsonb,
